// no overloading: one function, one runtime decision
const impl = {
  randomAccess: (a, i) => a[i],
  forward: (a, i) => { for (const v of a) if (i-- === 0) return v; },
};
function at(seq, i, tag) { return impl[tag](seq, i); }   // tag is a value, not a type

